import sys, os, re, collections
ROOT="AlgebraicJacobian"
def mod2path(m):
    return m.replace('.','/')+'.lean'
def path2mod(p):
    return p[:-5].replace('/','.')
imports=collections.defaultdict(set)
for dp,dn,fn in os.walk(ROOT):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            m=path2mod(p)
            with open(p) as fh:
                for line in fh:
                    line=line.strip()
                    if line.startswith('import AlgebraicJacobian'):
                        imports[m].add(line.split()[1])
                    elif line and not line.startswith('import') and not line.startswith('/-') and not line.startswith('--'):
                        break
