    seen=set()
    st=[m]
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x)
        for y in imports.get(x,()):
            if y not in seen: st.append(y)
    return seen
for arg in sys.argv[1:]:
    c=cone(arg)
    has=lambda n: n in c
    print(f"{arg}: cone={len(c)} files")
    for probe in ['AlgebraicJacobian.RiemannRoch.WeilDivisor','AlgebraicJacobian.Genus','AlgebraicJacobian.Albanese.CoheightBridge','AlgebraicJacobian.RiemannRoch.CurveCoheight']:
