import sys, os, collections
ROOT="AlgebraicJacobian"
def path2mod(p): return p[:-5].replace('/','.')
imports=collections.defaultdict(set)
allmods=set()
for dp,dn,fn in os.walk(ROOT):
    for f in fn:
        if not f.endswith('.lean'): continue
        p=os.path.join(dp,f); m=path2mod(p); allmods.add(m)
        for line in open(p):
            if line.startswith('import AlgebraicJacobian'):
                imports[m].add(line.split()[1].strip())
def cone(m):
    seen=set(); st=[m]
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x)
        st.extend(imports.get(x,()))
    return seen
PROBES=['AlgebraicJacobian.RiemannRoch.WeilDivisor','AlgebraicJacobian.Genus','AlgebraicJacobian.Albanese.CoheightBridge','AlgebraicJacobian.RiemannRoch.CurveCoheight','AlgebraicJacobian.RiemannRoch.CurveDivisorIndexBridge']
for arg in sys.argv[1:]:
    if arg not in allmods: print(arg, "NOT FOUND"); continue
    c=cone(arg)
    print(f"{arg}: cone={len(c)}")
    for probe in PROBES:
        if probe in c and probe!=arg: print("   CONTAINS", probe)
